bool ScriptSession::controlTarget(const UnitState& caster,const UnitState& target,const SpellInfo& s,bool visibility,unsigned owner){
    if(owner==UINT_MAX)owner=caster.owner;if((target.cycloned() && s.kind!=SpellKind::Purge) || target.removing || target.hidden() || number(target.life)<=0 || (visibility && !unitVisibleTo(target.handle,owner)))return false;if(s.kind==SpellKind::DarkConversion && definitions().property(target.type,"urac",definitions().field(target.type,"UnitData","race"))!=s.conversionRace)return false;auto& mask=s.allowed;auto classes=target.classifications(definitions().unitClasses(target.type));bool hostile=enemy(owner,target.owner),air=target.airborne();if(target.building && !mask.contains("structure"))return false;if((mask.contains("air") || mask.contains("ground")) && !((air && mask.contains("air")) || (target.groundTarget() && mask.contains("ground"))))return false;if(mask.contains("organic") && (target.building || classes.find("mechanical")!=std::string::npos))return false;if(mask.contains("nonsapper") && classes.find("sapper")!=std::string::npos)return false;if(mask.contains("nonancient") && classes.find("ancient")!=std::string::npos)return false;if(classes.find("ward")!=std::string::npos && !mask.contains("ward"))return false;if((mask.contains("hero") || mask.contains("nonhero")) && !(target.hero?mask.contains("hero"):mask.contains("nonhero")))return false;if((target.invulnerable || target.cycloned() || target.sleepProtected() || capability(target,"Avul")) && !mask.contains("invu") && !mask.contains("invulnerable"))return false;bool physical=(s.kind==SpellKind::Ensnare || s.kind==SpellKind::Web) && !s.magicControl;if(capability(target,"Amim") && !physical && s.kind!=SpellKind::Purge)return false;if((s.kind==SpellKind::Hex || s.kind==SpellKind::Polymorph) && (capability(target,"Arsk") || ghostFlag(target,GhostFlag::MorphImmune)))return false;if((s.kind==SpellKind::Hex || s.kind==SpellKind::Polymorph) && target.owner>=12 && unsigned(target.level)>s.creepLevel)return false;bool friends=mask.contains("friend") || mask.contains("allies"),enemies=mask.contains("enemy") || mask.contains("enemies");bool relations=friends || enemies || mask.contains("neutral") || mask.contains("self");if(relations && !((caster.handle==target.handle && mask.contains("self")) || (hostile && enemies) || (!hostile && friends) || (target.owner>=12 && mask.contains("neutral"))))return false;return !visibility || !hostile || fog(owner).state({target.x,target.y})==4;
}
std::optional<WorldPoint> ScriptSession::spellWidgetPoint(std::uint32_t id){if(alive(id,NativeKind::Unit)){auto u=units_.at(id);return WorldPoint{u->x,u->y};}if(alive(id,NativeKind::Destructable))return destructables_.at(id)->position;if(alive(id,NativeKind::Item)){auto item=items_.at(id);return WorldPoint{item->x,item->y};}return {};}
float ScriptSession::spellTargetCollision(std::uint32_t id) const {if(alive(id,NativeKind::Unit))return units_.at(id)->collision;if(alive(id,NativeKind::Destructable))return destructables_.at(id)->radius;return 0;}
bool ScriptSession::spellWidgetTarget(const UnitState& caster,std::uint32_t id,const SpellInfo& s,bool visibility){if(s.kind==SpellKind::Channel && s.allowed.contains("item") && alive(id,NativeKind::Item)){auto item=items_.at(id);return !item->removing && !item->holder && item->visible && number(item->life)>0 && (!visibility || fog(caster.owner).state({item->x,item->y})==4);}if(s.kind==SpellKind::EatTree){if(alive(id,NativeKind::Unit))return spellTarget(caster,*units_.at(id),s,visibility);return s.allowed.contains("tree") && eatTreeTarget(caster,id,visibility);}if(s.kind==SpellKind::GrabTree)return eatTreeTarget(caster,id,visibility);if(s.kind==SpellKind::Sentinel){if(!alive(id,NativeKind::Destructable))return false;auto d=destructables_.at(id);return d->tree && d->visible && !d->removed && d->life>0 && (!d->invulnerable || s.allowed.contains("invu")) && (!visibility || fog(caster.owner).state(d->position)==4);}if(alive(id,NativeKind::Unit))return spellTarget(caster,*units_.at(id),s,visibility);if(s.kind!=SpellKind::Purge || !s.allowed.contains("tree") || !alive(id,NativeKind::Destructable))return false;auto d=destructables_.at(id);return d->tree && d->visible && !d->removed && d->life>0 && !d->invulnerable && (!visibility || fog(caster.owner).state(d->position)==4);}
void ScriptSession::wakeUnit(std::uint32_t id){if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);bool changed=u->naturalSleep;if(changed){u->naturalSleep=false;u->naturalSleepWoken=true;}for(auto it=u->buffs.begin();it!=u->buffs.end();)if(it->second.kind==BuffKind::Sleep){releaseBuff(it->second);it=u->buffs.erase(it);changed=true;}else ++it;if(changed){u->animation.clear();u->animationIndex.reset();u->animationTime=0;++u->animationGeneration;}}
void ScriptSession::naturalSleepTick(){
    bool daytime=requireWorld().clock().daytime();using Cell=std::pair<int,int>;std::map<Cell,std::vector<std::shared_ptr<UnitState>>> cells;auto cell=[](float v){if(!std::isfinite(v))return 0;return int(std::clamp(std::floor(double(v)/256.),-1000000000.,1000000000.));};
    if(!daytime)for(auto& [id,u]:units_)if(!u->removing && !u->hidden() && number(u->life)>0)cells[{cell(number(u->x)),cell(number(u->y))}].push_back(u);
    for(auto& [id,u]:units_){
        bool eligible=(!u->naturalSleepDisabled && u->owner==12 && u->creepGuard && !u->building && !u->hero) || sourceAbility(*u,"ACsp").first || sourceAbility(*u,"Asla").first;
        if(daytime || !eligible || u->removing || u->hidden() || number(u->life)<=0){if(u->naturalSleep){u->naturalSleep=false;if(!u->sleeping()){u->animation.clear();u->animationIndex.reset();u->animationTime=0;++u->animationGeneration;}}if(daytime)u->naturalSleepWoken=false;continue;}
        if(u->naturalSleepWoken)continue;float x=number(u->x),y=number(u->y);int cx=cell(x),cy=cell(y);bool threatened=false;
        for(int dx=-1;dx<=1 && !threatened;++dx)for(int dy=-1;dy<=1 && !threatened;++dy)if(auto found=cells.find({cx+dx,cy+dy});found!=cells.end())for(auto& other:found->second)if(other->handle!=id && enemy(u->owner,other->owner) && std::hypot(number(other->x)-x,number(other->y)-y)<=200.f){threatened=true;break;}
        if(threatened){if(u->naturalSleep)wakeUnit(id);continue;}
        if(!u->naturalSleep && !u->sleeping() && !u->paused && !u->stunned() && !u->currentOrder && u->route.empty() && !u->combat.target && !u->cast){u->naturalSleep=true;u->animation="Sleep";u->animationIndex.reset();u->animationTime=0;++u->animationGeneration;}
    }
}
float ScriptSession::spellHealAmount(const UnitState& u,float amount){if(!u.ethereal())return amount;float factor=gameplayNumber("EtherealHealBonus",1.66f);if(factor<0 || factor>100)throw std::runtime_error("Ethereal healing factor outside source range");return amount*factor;}
void ScriptSession::controlBuff(UnitState& u,UnitBuff& b,const SpellInfo& s){
    b.total=b.remaining;if(b.kind==BuffKind::Net){b.groundsAir=u.movementType=="fly";b.groundHeight=s.secondary;b.landTime=s.amount;updateGrounding(u,0);}if(b.kind==BuffKind::Sleep){b.damageGuard=std::min(double(s.amount),b.remaining);if(s.guardBuff && b.damageGuard>0){auto visual=s;visual.ability=s.guardBuff;auto effects=spellVisual(visual,"TargetArt",u.handle,{u.x,u.y},false);for(auto id:effects)effectExpires(id,simulationTime_+b.damageGuard);b.visuals.insert(b.visuals.end(),effects.begin(),effects.end());}}if(b.kind==BuffKind::Purge){b.lockRemaining=std::min(double(u.hero?s.castDelay:s.impactDelay),b.remaining);b.recoveryMoveSteps=float(s.recoveryMoveSteps);b.recoveryAttackSteps=float(s.recoveryAttackSteps);controlBuffTick(b,0);}if(b.kind==BuffKind::Banish){b.moveReduction=s.moveReduction;b.attackReduction=s.attackReduction;}
}
void ScriptSession::controlBuffTick(UnitBuff& b,double elapsed){if(b.kind!=BuffKind::Impale)b.lockRemaining=std::max(0.,b.lockRemaining-elapsed);b.damageGuard=std::max(0.,b.damageGuard-elapsed);if(b.kind!=BuffKind::Purge && b.kind!=BuffKind::CargoDizzy)return;auto reduction=[&](float steps){if(!steps || b.total<=0)return 0.f;float factor=std::max(1.f,float(std::ceil(std::clamp(b.remaining/b.total,0.,1.)*steps)));return 1-1/factor;};b.moveReduction=reduction(b.recoveryMoveSteps);b.attackReduction=reduction(b.recoveryAttackSteps);}
void ScriptSession::updateGrounding(UnitState& u,double delta){
    if(u.movementType!="fly" && !u.grounding)return;bool down=false;float desired=u.flyHeight,rate=0;for(auto& [id,b]:u.buffs)if(b.kind==BuffKind::Net && b.groundsAir){down=true;desired=std::min(desired,b.groundHeight);rate=std::max(rate,std::abs(u.flyHeight-b.groundHeight)/std::max(1.f/32,b.landTime));}if(down && !u.grounding)u.grounding=GroundingState{u.flyHeight,rate};if(!u.grounding)return;auto& landing=*u.grounding;if(!down && landing.rate<=0){u.grounding.reset();return;}if(down)landing.rate=std::max(landing.rate,rate);float difference=desired-landing.height,step=float(delta)*landing.rate;if(step>0)landing.height+=std::clamp(difference,-step,step);else if(difference==0)landing.height=desired;if(!down && std::abs(landing.height-desired)<.01f)u.grounding.reset();
}
void ScriptSession::purgeSpell(std::uint32_t source,std::uint32_t id,const SpellInfo& s){
    if(!alive(source,NativeKind::Unit))return;if(alive(id,NativeKind::Destructable)){auto d=destructables_.at(id);spellVisual(s,"Specialart",0,d->position);destructableLife(id,0);return;}if(!alive(id,NativeKind::Unit))return;auto caster=units_.at(source),target=units_.at(id);bool hostile=enemy(caster->owner,target->owner);for(auto it=target->buffs.begin();it!=target->buffs.end();)if(!it->second.physical && it->second.dispellable){releaseBuff(it->second);it=target->buffs.erase(it);}else ++it;spellVisual(s,"Specialart",id,{target->x,target->y});if(hostile){target->mana=real(std::max(0.f,number(target->mana)-s.manaLoss));if(target->illusion)unitLife(runtime_.handle("unit",id),{},source);else if(s.loss>0 && !capability(*target,"Arsk") && target->typeFlag(10,target->sourceSummoned || target->summoner!=0 || bool(target->timedLife)))damageUnit(source,id,s.loss,0,26);if(alive(source,NativeKind::Unit) && alive(id,NativeKind::Unit) && number(target->life)>0)applyBuff(id,source,s,BuffKind::Purge);}
}
void ScriptSession::controlEffect(const SpellMissile& missile){
    if(!alive(missile.source,NativeKind::Unit))return;auto s=missile.spell;if(s.kind==SpellKind::Purge){if(spellWidgetTarget(*units_.at(missile.source),missile.target,s,false))purgeSpell(missile.source,missile.target,s);return;}if(!alive(missile.target,NativeKind::Unit))return;auto u=units_.at(missile.target);if(s.kind==SpellKind::Ensnare || s.kind==SpellKind::Web){if(u->movementType!="fly")s.buff=s.groundBuff;applyBuff(missile.target,missile.source,s,BuffKind::Net,!s.magicControl);return;}if(s.kind==SpellKind::Hex || s.kind==SpellKind::Polymorph){morphEffect(missile.source,missile.target,s);return;}if(s.kind==SpellKind::Cyclone){cycloneEffect(missile.source,missile.target,s);return;}if(s.kind==SpellKind::Sleep){applyBuff(missile.target,missile.source,s,BuffKind::Sleep);return;}if(s.kind==SpellKind::DarkConversion){applyBuff(missile.target,missile.source,s,BuffKind::DarkConversion);return;}if(s.kind==SpellKind::Banish){applyBuff(missile.target,missile.source,s,BuffKind::Banish);return;}throw std::runtime_error("Missing source control consumer");
}
void ScriptSession::bindControlNatives(){
    for(auto [addName,queryName,code]:std::initializer_list<std::tuple<const char*,const char*,const char*>>{{"UnitAddSleep","UnitCanSleep","ACsp"},{"UnitAddSleepPerm","UnitCanSleepPerm","Asla"}}){
        bind(addName,"nothing",{"unit","boolean"},[this,code](auto& vm,auto a){if(!alive(a[0].bits,NativeKind::Unit))return vm.nothing();auto u=units_.at(a[0].bits);if(ObjectData::code(code)==ObjectData::code("ACsp"))u->naturalSleepDisabled=!a[1].bits;auto ability=sourceAbility(*u,code).first;if(a[1].bits && !ability)vm.invoke("UnitAddAbility",std::array{a[0],vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(code)))});else if(!a[1].bits && ability)vm.invoke("UnitRemoveAbility",std::array{a[0],vm.integer(std::bit_cast<std::int32_t>(ability))});return vm.nothing();});
        bind(queryName,"boolean",{"unit"},[this,code](auto& vm,auto a){return vm.boolean(alive(a[0].bits,NativeKind::Unit) && sourceAbility(*units_.at(a[0].bits),code).first!=0);});
    }
    bind("UnitIsSleeping","boolean",{"unit"},[this](auto& vm,auto a){return vm.boolean(alive(a[0].bits,NativeKind::Unit) && units_.at(a[0].bits)->sleeping());});
    bind("UnitWakeUp","nothing",{"unit"},[this](auto& vm,auto a){wakeUnit(a[0].bits);return vm.nothing();});
}
